export class PubSubSystem {
  constructor() {
    this.events = {};
  }

  subscribe(event, handler) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(handler);
  }

  publish(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(handler => handler(data));
    }
  }

  escalate(event, data, escalationHandler) {
    if (this.events[event]) {
      const responses = this.events[event].map(handler => handler(data));
      if (responses.some(response => response.requiresEscalation)) {
        escalationHandler(data);
      }
    }
  }
}